mapper.select:
SELECT DISTINCT

FROM SPOT_TRAVEL st

    JOIN SPOT_TAG      s_tag2 ON s_tag2.spot_idx = st.spot_idx
    JOIN SPOT_TAG_LIST tl2    ON tl2.tag_idx     = s_tag2.tag_idx


    COALESCE(st.spot_active, 0) = 0

        AND (
            st.name        LIKE CONCAT('%', #{keyword}, '%')
            OR st.region   LIKE CONCAT('%', #{keyword}, '%')
            OR st.address  LIKE CONCAT('%', #{keyword}, '%')
        )


        AND st.region = #{region}


        AND tl2.tag_name = #{theme}


ORDER BY rating_avg_real DESC, review_count_real DESC
LIMIT  #{pageSize}
OFFSET #{offset}

SELECT COUNT(DISTINCT st.spot_idx) FROM SPOT_TRAVEL st
JOIN SPOT_TAG s_tag2 ON s_tag2.spot_idx = st.spot_idx JOIN SPOT_TAG_LIST tl2 ON tl2.tag_idx = s_tag2.tag_idx
COALESCE(st.spot_active, 0) = 0
AND ( st.name LIKE CONCAT('%', #{keyword}, '%') OR st.region LIKE CONCAT('%', #{keyword}, '%') OR st.address LIKE CONCAT('%', #{keyword}, '%') )
AND st.region = #{region}
AND tl2.tag_name = #{theme}

SELECT

FROM SPOT_TRAVEL st

    COALESCE(st.spot_active, 0) = 0

        AND (
            st.name   LIKE CONCAT('%', #{keyword}, '%')
            OR st.region LIKE CONCAT('%', #{keyword}, '%')
        )


ORDER BY rating_avg_real DESC, review_count_real DESC
LIMIT  #{pageSize}
OFFSET #{offset}

SELECT

FROM SPOT_TRAVEL st

    COALESCE(st.spot_active, 0) = 0

        AND (
            st.name   LIKE CONCAT('%', #{keyword}, '%')
            OR st.region LIKE CONCAT('%', #{keyword}, '%')
        )


ORDER BY like_count_real DESC, rating_avg_real DESC
LIMIT  #{pageSize}
OFFSET #{offset}

SELECT

FROM SPOT_TRAVEL st

JOIN SPOT_FAVORITE sf ON sf.spot_idx = st.spot_idx
                      AND sf.user_idx = #{loginUserIdx}

    COALESCE(st.spot_active, 0) = 0


        AND (
            st.name        LIKE CONCAT('%', #{keyword}, '%')
            OR st.region   LIKE CONCAT('%', #{keyword}, '%')
            OR st.address  LIKE CONCAT('%', #{keyword}, '%')
        )



ORDER BY sf.created_at DESC
LIMIT  #{pageSize}
OFFSET #{offset}

SELECT COUNT(*)
FROM SPOT_TRAVEL
WHERE spot_id = #{spotId}

